    echo "  [OK] Rollback of notify_analyst completed"
}

verify_3() {
    echo "[VERIFY 3] notify_analyst -> SOC Team"
    # Notification logged; verify via platform audit trail.
}

# =======================================
# Main Execution
# =======================================
echo ""
echo "Starting execution of 3 action(s)..."
echo ""

if $ROLLBACK; then
    rollback_3
    rollback_2
    rollback_1
elif [[ -n "$SINGLE_ACTION" ]]; then
    case "$SINGLE_ACTION" in
        1) action_1 ;;
        2) action_2 ;;
        3) action_3 ;;
        *) echo "Unknown action: $SINGLE_ACTION"; exit 1 ;;
    esac
else
    action_1
    action_2
    action_3
fi

echo ""
echo "Execution completed."
